window.docContents[40].resolve({"/Planned-constructions/#Core-C______--Planned-constructions":{"contents":"Constructions of the Core C++ design without rules or implementation yet. They appear in the graph and in the summary as pending work, in the order of the UD.\n\n\n\nThe design lists no construction outside the units already written. The\nunits I to VI cover the subset, and this chapter stays as the place for a\nconstruction the course decides to add.\n\n\n","context":"Core C++","header":"8. Planned constructions","id":"/Planned-constructions/#Core-C______--Planned-constructions"}});